#!/system/bin/shexport PATH="/system/bin:/system/xbin:/data/adb/ksu/bin:$PATH"MODDIR="${0%/*}"STATE_DIR="/data/adb/xmsrom_qs_perf"GUARD="$STATE_DIR/boot_guard"LOG="$STATE_DIR/boot.log"log() { printf '%s %s\n' "$(date '+%H:%M:%S' 2>/dev/null || echo 'svc')" "$*" >> "$LOG"; }(  i=0  while [ "$i" -lt 120 ]; do    if [ "$(getprop sys.boot_completed)" = "1" ] && pm path android >/dev/null 2>&1 && (pidof com.android.systemui >/dev/null 2>&1 || pgrep -f com.android.systemui >/dev/null 2>&1); then      break    fi    sleep 1    i=$((i + 1))  done  sleep 4  bc="$(getprop sys.boot_completed 2>/dev/null)"  sp="$(pidof com.android.systemui 2>/dev/null || pgrep -f com.android.systemui 2>/dev/null || true)"  if [ "$bc" = "1" ] && [ -n "$sp" ]; then    rm -f "$GUARD"    log "BOOT_OK: guard cleared (pid=$sp)"  else    log "WARN: boot health incomplete (bc=$bc pid=$sp); guard retained"  fi) >/dev/null 2>&1 &